messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Car Race Animation</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #000; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky Blue
        scene.fog = new THREE.Fog(0x87CEEB, 20, 100);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 5, 12);
        camera.lookAt(0, 0, -10);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const hemiLight = new THREE.HemisphereLight(0xffffff, 0x444444, 0.8);
        scene.add(hemiLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(10, 20, 10);
        dirLight.castShadow = true;
        dirLight.shadow.camera.top = 20;
        dirLight.shadow.camera.bottom = -20;
        dirLight.shadow.camera.left = -20;
        dirLight.shadow.camera.right = 20;
        scene.add(dirLight);

        // --- Ground ---
        const planeGeometry = new THREE.PlaneGeometry(200, 200);
        const planeMaterial = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const ground = new THREE.Mesh(planeGeometry, planeMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.position.y = -0.1;
        ground.receiveShadow = true;
        scene.add(ground);

        // --- Track & Finish Line ---
        // We will animate the texture of the track to simulate movement, rather than moving the cars forward indefinitely
        const trackWidth = 10;
        const trackLength = 40; // Length of one loop segment

        // Create a texture for the track with a finish line
        const canvasTexture = document.createElement('canvas');
        canvasTexture.width = 512;
        canvasTexture.height = 512;
        const ctx = canvasTexture.getContext('2d');

        // Road Surface
        ctx.fillStyle = '#555';
        ctx.fillRect(0, 0, 512, 512);

        // Lane markings
        ctx.fillStyle = '#FFF';
        ctx.fillRect(250, 0, 12, 512); // Center line

        // Finish Line (Checkered pattern)
        ctx.fillStyle = '#000';
        for(let r=0; r<4; r++) {
            for(let c=0; c<16; c++) {
                if((r+c)%2 === 0) {
                    ctx.fillRect(c * 32, 0, 32, 128); // Bottom quarter
                    ctx.fillRect(c * 32, 384, 32, 128); // Top quarter
                }
            }
        }

        const trackTexture = new THREE.CanvasTexture(canvasTexture);
        trackTexture.wrapS = THREE.RepeatWrapping;
        trackTexture.wrapT = THREE.RepeatWrapping;
        trackTexture.repeat.set(1, 10); // Repeat lengthwise

        const trackGeometry = new THREE.PlaneGeometry(trackWidth, 400);
        const trackMaterial = new THREE.MeshStandardMaterial({ 
            map: trackTexture,
            roughness: 0.8 
        });
        const track = new THREE.Mesh(trackGeometry, trackMaterial);
        track.rotation.x = -Math.PI / 2;
        track.receiveShadow = true;
        scene.add(track);

        // --- Car Factory ---
        function createCar(color) {
            const carGroup = new THREE.Group();

            // Chassis
            const chassisGeo = new THREE.BoxGeometry(1.8, 0.8, 3.5);
            const chassisMat = new THREE.MeshStandardMaterial({ color: color });
            const chassis = new THREE.Mesh(chassisGeo, chassisMat);
            chassis.position.y = 0.8;
            chassis.castShadow = true;
            carGroup.add(chassis);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(1.4, 0.6, 1.8);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.set(0, 1.6, -0.2);
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.4, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

            const positions = [
                { x: -1, z: 1.2 }, { x: 1, z: 1.2 },
                { x: -1, z: -1.2 }, { x: 1, z: -1.2 }
            ];

            positions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(pos.x, 0.4, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            return carGroup;
        }

        const redCar = createCar(0xff0000);
        const blueCar = createCar(0x0000ff);

        // Initial positions (Z is depth, negative is forward)
        redCar.position.set(-4, 0, 0);
        blueCar.position.set(4, 0, 0);

        scene.add(redCar);
        scene.add(blueCar);

        // --- Animation State ---
        const speedBlue = 0.3; // Starts faster
        const speedRed = 0.2;  // Starts slower

        // Animation variables
        let time = 0;
        const raceDuration = 600; // Frames for one race
        let cycleTime = 0;

        // Race phases:
        // 0-200: Blue leads
        // 200-400: Red catches up
        // 400-600: Red wins, reset

        function animate() {
            requestAnimationFrame(animate);

            cycleTime++;

            // Reset logic every 600 frames (approx 10 sec at 60fps)
            if (cycleTime > raceDuration) {
                cycleTime = 0;
            }

            // Calculate relative positions based on cycleTime
            // We want the finish line to pass under them.
            // Effectively, we move the track texture backwards to simulate forward movement

            let progress = 0;
            let redSpeed = 0;
            let blueSpeed = 0;

            if (cycleTime < 200) {
                // Phase 1: Blue leads comfortably
                progress = cycleTime * 0.5;
                redSpeed = 0.2 + Math.sin(cycleTime * 0.02) * 0.05; // Slight wobble
                blueSpeed = 0.35;
            } else if (cycleTime < 400) {
                // Phase 2: Red accelerates, Blue maintains or slows slightly
                const t = (cycleTime - 200) / 200;
                redSpeed = 0.2 + t * 0.25; // Linear acceleration to 0.45
                blueSpeed = 0.35 - t * 0.05; // Slow down slightly
                progress = 100 + (cycleTime - 200) * (redSpeed + blueSpeed) / 2;
            } else {
                // Phase 3: Red crosses line, reset
                const t = (cycleTime - 400) / 200;
                redSpeed = 0.45;
                blueSpeed = 0.3;
                progress = 200 + (cycleTime - 400) * 0.5;
            }

            // Update Track Texture to simulate movement
            // The track texture repeats 10 times vertically. 
            // Moving offset by 1.0 moves one full segment.
            trackTexture.offset.y = -(progress / 400) % 1; 

            // Update Car Positions (Z-axis)
            // We keep them relatively close to the camera but moving "forward" (negative Z)
            // To keep them in frame, we actually move the camera with them too.

            const carZ = -progress;

            redCar.position.z = carZ;
            blueCar.position.z = carZ - (cycleTime < 200 ? 30 : 0); // Blue starts ahead, gap closes

            // Camera follows the race
            // We interpolate camera Z to keep both cars in view
            const targetCamZ = carZ + 12;
            camera.position.z += (targetCamZ - camera.position.z) * 0.1;

            // Slight camera sway to follow the leader
            const leaderX = (cycleTime < 300) ? 4 : -4; // Blue then Red
            camera.position.x += (leaderX * 0.5 - camera.position.x) * 0.05;

            // Car Bouncing/Rolling animation
            const bounce = Math.sin(time * 20) * 0.05;
            redCar.position.y = bounce;
            blueCar.position.y = bounce;

            time += 0.1;

            renderer.render(scene, camera);
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
```
